using System.IO;
namespace FontFilter;
public sealed class FontStore:IDisposable
{
 readonly NativeSqlite db;readonly object gate=new();
 const string Columns="id,family,face,source,vendor,auto,manual,summary,url,updated,active,cjk,CASE WHEN EXISTS(SELECT 1 FROM favorites WHERE favorites.family=fonts.family) THEN '1' ELSE '0' END";
 public FontStore(string path){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);DatabasePath=Path.GetFullPath(path);db=new NativeSqlite(path);db.Query("PRAGMA journal_mode=WAL");db.Query("CREATE TABLE IF NOT EXISTS fonts(id TEXT PRIMARY KEY,family TEXT NOT NULL,face TEXT NOT NULL,source TEXT NOT NULL,vendor TEXT NOT NULL,auto TEXT NOT NULL DEFAULT '',manual TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',updated TEXT NOT NULL DEFAULT '',active TEXT NOT NULL DEFAULT '1')");if(!db.Query("PRAGMA table_info(fonts)").Any(r=>r[1]=="cjk"))db.Query("ALTER TABLE fonts ADD COLUMN cjk TEXT NOT NULL DEFAULT '?'");db.Query("CREATE INDEX IF NOT EXISTS family_idx ON fonts(family)");db.Query("CREATE TABLE IF NOT EXISTS official_tags(id TEXT PRIMARY KEY,tags TEXT NOT NULL)");db.Query("CREATE TABLE IF NOT EXISTS favorites(family TEXT PRIMARY KEY)");db.Query("CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL)");}
 static FontRecord Read(string[] r)=>new(r[0],r[1],r[2],r[3],r[4]){AutoTags=r[5],ManualTags=r[6],Summary=r[7],Url=r[8],Updated=r[9],Active=r[10]=="1",IsFavorite=r[12]=="1",SupportsChinese=r[11]=="1"?true:r[11]=="0"?false:null};
 public void Upsert(FontRecord f){lock(gate){var prev=db.Query("SELECT "+Columns+" FROM fonts WHERE id=?",f.Id).FirstOrDefault();var prior=prev==null?null:Read(prev);f.Summary=prior?.Summary??f.Summary;var cjk=f.SupportsChinese??prior?.SupportsChinese;var tagged=f with{SupportsChinese=cjk};db.Query("INSERT INTO fonts(id,family,face,source,vendor,auto,active,cjk) VALUES(?,?,?,?,?,?,'1',?) ON CONFLICT(id) DO UPDATE SET family=excluded.family,face=excluded.face,source=excluded.source,vendor=excluded.vendor,auto=excluded.auto,active='1',cjk=excluded.cjk",f.Id,f.Family,f.Face,f.Source,f.Vendor,TagsFor(tagged),cjk==true?"1":cjk==false?"0":"?");}}
 public void RefreshRuleTags(){lock(gate){var saved=db.Query("SELECT value FROM metadata WHERE key='tag-version'").FirstOrDefault()?[0];if(saved==TagCatalog.Version.ToString())return;db.Query("BEGIN IMMEDIATE");try{foreach(var f in All())db.Query("UPDATE fonts SET auto=? WHERE id=?",TagsFor(f),f.Id);db.Query("INSERT INTO metadata(key,value) VALUES('tag-version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",TagCatalog.Version.ToString());db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}}
 public void UpsertBatch(IEnumerable<FontRecord> fonts){lock(gate){db.Query("BEGIN IMMEDIATE");try{foreach(var f in fonts)Upsert(f);db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}}
 public List<FontRecord> All(){lock(gate)return db.Query("SELECT "+Columns+" FROM fonts WHERE active='1' ORDER BY family,face").Select(Read).ToList();}
 public List<FontRecord> Search(string query,bool favoritesOnly=false,bool matchAny=false){lock(gate){var terms=TagRules.Terms(query);var expression="family||' '||face||' '||vendor||' '||auto||' '||manual||' '||summary";var sql="SELECT "+Columns+" FROM fonts WHERE active='1'";if(favoritesOnly)sql+=" AND EXISTS(SELECT 1 FROM favorites WHERE favorites.family=fonts.family)";if(terms.Length>0)sql+=" AND ("+string.Join(matchAny?" OR ":" AND ",terms.Select(t=>"instr(lower("+expression+"),lower(?))>0"))+")";sql+=" ORDER BY family,face";return db.Query(sql,terms).Select(Read).ToList();}}
 public int FavoriteCount{get{lock(gate)return int.Parse(db.Query("SELECT COUNT(DISTINCT fonts.family) FROM fonts INNER JOIN favorites ON favorites.family=fonts.family WHERE active='1'")[0][0]);}}
 public void SetFavorite(IEnumerable<string> families,bool favorite){lock(gate){db.Query("BEGIN IMMEDIATE");try{foreach(var family in families.Distinct())if(favorite)db.Query("INSERT OR IGNORE INTO favorites(family) VALUES(?)",family);else db.Query("DELETE FROM favorites WHERE family=?",family);db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}}
 public void SetManual(IEnumerable<string> ids,string tags){lock(gate){db.Query("BEGIN IMMEDIATE");try{foreach(var id in ids)db.Query("UPDATE fonts SET manual=? WHERE id=?",tags.Trim(),id);db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}}
 public void SaveMetadata(string id,string summary,string url){lock(gate){var f=db.Query("SELECT "+Columns+" FROM fonts WHERE id=?",id).Select(Read).Single();db.Query("UPDATE fonts SET summary=?,url=?,updated=?,auto=? WHERE id=?",summary,url,DateTimeOffset.Now.ToString("O"),TagsFor(f with{Summary=summary}),id);}}
 public void MarkAbsent(ISet<string> present){lock(gate){db.Query("BEGIN IMMEDIATE");try{foreach(var f in All())if(!present.Contains(f.Id))db.Query("UPDATE fonts SET active='0' WHERE id=?",f.Id);db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}}
 public OfficialImportResult ImportOfficial(IEnumerable<OfficialMatch> matches){lock(gate){var items=matches.ToArray();AttachOfficialTags(items);int added=0,existing=0,empty=0;db.Query("BEGIN IMMEDIATE");try{foreach(var match in items.DistinctBy(m=>m.Local.Id)){var text=OfficialCatalogue.Format(match.Source);if(text.Length==0||!Uri.TryCreate(match.Source.SourceUrl,UriKind.Absolute,out var uri)||!OfficialMetadataService.IsAllowed(uri)){empty++;continue;}var row=db.Query("SELECT "+Columns+" FROM fonts WHERE id=? AND active='1'",match.Local.Id).FirstOrDefault();if(row==null)continue;var f=Read(row);if(!string.IsNullOrWhiteSpace(f.Summary)){existing++;continue;}SaveMetadata(f.Id,text,match.Source.SourceUrl);added++;}db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}return new(added,existing,empty);}}

 string TagsFor(FontRecord f)=>string.Join(" ",TagRules.Terms(TagRules.ForFont(f)+" "+(db.Query("SELECT tags FROM official_tags WHERE id=?",f.Id).FirstOrDefault()?[0]??"")));
 public int AttachOfficialTags(IEnumerable<OfficialMatch> matches){lock(gate){int count=0;db.Query("BEGIN IMMEDIATE");try{foreach(var match in matches.DistinctBy(m=>m.Local.Id)){if(!Uri.TryCreate(match.Source.SourceUrl,UriKind.Absolute,out var u)||!OfficialMetadataService.IsAllowed(u))continue;var row=db.Query("SELECT "+Columns+" FROM fonts WHERE id=? AND active='1'",match.Local.Id).FirstOrDefault();if(row==null)continue;var tags=string.Join(" ",TagRules.Terms(TagRules.Extract(match.Source.Family+" "+match.Source.Summary+" "+string.Join(" ",match.Source.Tags))+" "+string.Join(" ",match.Source.Tags.Where(t=>t.Length<=32))));if(tags.Length==0)continue;db.Query("INSERT INTO official_tags(id,tags) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET tags=excluded.tags",match.Local.Id,tags);db.Query("UPDATE fonts SET auto=? WHERE id=?",TagsFor(Read(row)),match.Local.Id);count++;}db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}return count;}}
 public Dictionary<string,int> TagCounts(IEnumerable<string> tags){var families=All().GroupBy(f=>f.Family).Select(g=>g.Select(f=>f.SearchText).ToArray()).ToArray();return tags.Distinct(StringComparer.OrdinalIgnoreCase).ToDictionary(tag=>tag,tag=>{var terms=TagRules.Terms(tag);return families.Count(f=>f.Any(text=>terms.All(t=>text.Contains(t,StringComparison.OrdinalIgnoreCase))));},StringComparer.OrdinalIgnoreCase);}
 public List<TagDefinition> AvailableTagDefinitions(){var known=TagCatalog.All.Select(t=>t.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);return TagCatalog.All.Concat(All().SelectMany(f=>TagRules.Terms(f.AutoTags+" "+f.ManualTags)).Where(t=>!known.Contains(t)).Distinct().OrderBy(t=>t).Select(t=>new TagDefinition("官网及自定义",t,t))).ToList();}

 public List<FontRecord> ExportAll(){lock(gate)return db.Query("SELECT "+Columns+" FROM fonts").Select(Read).ToList();}
 public void Backup(string destination){lock(gate)NativeSqlite.Snapshot(DatabasePath,destination);}
 public string DatabasePath{get;private set;}="";
 public void MergeAnnotations(IEnumerable<(FontRecord Current,FontRecord Old)> pairs)
 {
  lock(gate){db.Query("BEGIN IMMEDIATE");try{foreach(var (current,old) in pairs){
   var manual=string.Join(" ",TagRules.Terms(current.ManualTags+" "+old.ManualTags));
   var mergedSummary=string.IsNullOrWhiteSpace(current.Summary)?old.Summary:current.Summary;
   db.Query("UPDATE fonts SET manual=?,summary=?,url=?,auto=? WHERE id=?",manual,mergedSummary,string.IsNullOrWhiteSpace(current.Summary)?old.Url:current.Url,TagsFor(current with{Summary=mergedSummary}),current.Id);
   if(old.IsFavorite)db.Query("INSERT OR IGNORE INTO favorites(family) VALUES(?)",current.Family);
  }db.Query("COMMIT");}catch{db.Query("ROLLBACK");throw;}}
 }
 public void Dispose(){lock(gate)db.Dispose();}
}
